const input = $input.first().json;

const safe = (v) => String(v ?? '').replace(/\r\n/g, '\n');
const today = new Date().toISOString().slice(0, 10);

const taskId = safe(input.task_id);
const fileName = `${taskId.replace(/[^A-Za-z0-9_-]/g, '_')}.md`;
const relativePath = `docs/03_taskpacks/${fileName}`;

const ensureArray = (x) => {
  if (Array.isArray(x)) return x;
  if (typeof x === 'string' && x.trim()) {
    try {
      const parsed = JSON.parse(x);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [x];
    }
  }
  return [];
};

const mdList = (arr) => {
  const a = ensureArray(arr).map(safe).filter(Boolean);
  return a.length ? a.map((v) => `- ${v}`).join('\n') : '-';
};

const title = safe(input.title).replace(/"/g, '\\"');

const content = [
  '---',
  `task_id: ${taskId}`,
  `title: "${title}"`,
  `task_type: ${safe(input.task_type) || 'code'}`,
  `complexity: ${safe(input.complexity) || 'normal'}`,
  `model_override: ${safe(input.model_override) || 'auto'}`,
  `execution_runtime: ${safe(input.execution_runtime) || 'wsl'}`,
  `requires_mcp: ${safe(input.requires_mcp) || ''}`,
  '---',
  '',
  `# TASK-PACK: ${taskId}`,
  '',
  '## 基本信息',
  '',
  '| 字段 | 值 |',
  '|------|---|',
  `| **Task ID** | ${taskId} |`,
  `| **Level** | ${safe(input.level) || 'L3'} |`,
  `| **Owner** | ${safe(input.owner) || 'L0_producer'} |`,
  `| **Executor** | ${safe(input.executor) || safe(input.role) || 'L3_engineer'} |`,
  `| **Reviewer** | ${safe(input.reviewer) || 'L2_tools_lead'} |`,
  `| **创建日期** | ${today} |`,
  '| **状态** | Ready |',
  '',
  '## 1. Outcome（可观察结果）',
  '',
  safe(input.outcome) || '-',
  '',
  '## 2. Allowed Inputs（允许引用的输入）',
  '',
  mdList(input.allowed_inputs),
  '',
  '## 3. Deliverables（必须交付物）',
  '',
  mdList(input.deliverables),
  '',
  '## 4. Constraints（硬约束 / 禁止事项）',
  '',
  mdList(input.constraints),
  '',
  '## 5. Acceptance Checklist（验收清单）',
  '',
  mdList(input.acceptance),
  '',
  '## 6. Self-Check（执行者自检回执格式）',
  '',
  '```',
  '【完成内容】',
  '- ...',
  '',
  '【输出文件】',
  '- ...',
  '',
  '【自检】',
  '- [ ] ...',
  '',
  '【风险与未完成】',
  '- (如有)',
  '```',
  '',
  '## 9. Notes（备注）',
  '',
  safe(input.notes) || '-',
  '',
].join('\n');

return {
  json: {
    ...input,
    task_pack_path: relativePath,
    task_pack_abs_path: `${safe(input.project_root)}/${relativePath}`,
    task_pack_content: content,
  },
};
